#!/usr/bin/env node
/**
 * Nexushouse update script — run with: node apply-update.js
 * (from the project root)
 *
 * This round: a full rework of the preloader and page transitions,
 * built around the site's own notch shape instead of a generic
 * spinner/fade. See DiagonalWipe.tsx and Loader.tsx for the details.
 *
 * After running this, review the diff (`git diff`) and commit as usual.
 */
const fs = require("fs");
const path = require("path");

const FILES = [
  {
    "path": "src/app/globals.css",
    "b64": ""
  },
  {
    "path": "src/app/insights/[slug]/page.tsx",
    "b64": ""
  },
  {
    "path": "src/app/insights/page.tsx",
    "b64": ""
  },
  {
    "path": "src/app/layout.tsx",
    "b64": ""
  },
  {
    "path": "src/app/legal/page.tsx",
    "b64": ""
  },
  {
    "path": "src/app/not-found.tsx",
    "b64": ""
  },
  {
    "path": "src/app/services/business-registration/page.tsx",
    "b64": ""
  },
  {
    "path": "src/app/services/page.tsx",
    "b64": ""
  },
  {
    "path": "src/app/studio/page.tsx",
    "b64": ""
  },
  {
    "path": "src/app/work/[slug]/page.tsx",
    "b64": ""
  },
  {
    "path": "src/app/work/page.tsx",
    "b64": ""
  },
  {
    "path": "src/components/Contact.tsx",
    "b64": ""
  },
  {
    "path": "src/components/Hero.tsx",
    "b64": ""
  },
  {
    "path": "src/components/Loader.tsx",
    "b64": ""
  },
  {
    "path": "src/components/PageTransition.tsx",
    "b64": ""
  },
  {
    "path": "src/components/DiagonalWipe.tsx",
    "b64": ""
  },
  {
    "path": "src/components/TransitionOverlay.tsx",
    "b64": ""
  }
];

let written = 0;
for (const { path: relPath, b64 } of FILES) {
  const abs = path.join(__dirname, relPath);
  fs.mkdirSync(path.dirname(abs), { recursive: true });
  fs.writeFileSync(abs, Buffer.from(b64, "base64"));
  console.log("wrote", relPath);
  written++;
}

console.log(`\nDone: ${written} file(s) written.`);
console.log("Next: git status / git diff, then commit and push.");
